// /admin and /app/* — SERVER-SIDE gated. Tools live inside this function bundle (base64),
// NOT in the public folder. Returned ONLY after the signed session cookie verifies.
const crypto = require("crypto");
const TOOLS = { "rtgs": '', "id-card": '', "letter": '' };
const DASHBOARD = '<!DOCTYPE html>\n<html lang="en"><head>\n<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Admin Panel — P.G. Service Station</title>\n<style>\n  *{box-sizing:border-box;margin:0;padding:0}\n  body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;background:#eef2f7;color:#0f172a;min-height:100vh}\n  header{background:#003f87;color:#fff;padding:18px 28px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}\n  header .brand{font-size:19px;font-weight:800;letter-spacing:.3px}\n  header .brand span{display:block;font-size:12px;font-weight:500;opacity:.8;margin-top:2px}\n  .logout{background:rgba(255,255,255,.15);color:#fff;text-decoration:none;padding:9px 16px;border-radius:8px;font-size:14px;font-weight:600;border:1px solid rgba(255,255,255,.3)}\n  .logout:hover{background:rgba(255,255,255,.28)}\n  .bar{height:5px;background:#ffd600}\n  .wrap{max-width:960px;margin:0 auto;padding:40px 20px}\n  .hi{font-size:24px;font-weight:800;margin-bottom:6px}\n  .sub{color:#475569;margin-bottom:28px;font-size:15px}\n  .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:20px}\n  .card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:26px;text-decoration:none;color:inherit;display:block;transition:transform .12s,box-shadow .12s;box-shadow:0 1px 3px rgba(0,0,0,.06)}\n  .card:hover{transform:translateY(-3px);box-shadow:0 10px 24px rgba(0,63,135,.14);border-color:#003f87}\n  .ico{width:52px;height:52px;border-radius:12px;background:#e8f0fb;display:flex;align-items:center;justify-content:center;font-size:26px;margin-bottom:16px}\n  .card h3{font-size:18px;font-weight:800;margin-bottom:6px}\n  .card p{color:#64748b;font-size:14px;line-height:1.5}\n  .open{margin-top:16px;color:#003f87;font-weight:700;font-size:14px}\n  footer{text-align:center;color:#94a3b8;font-size:12px;padding:24px}\n</style></head>\n<body>\n  <header><div class="brand">P.G. Service Station<span>Admin Control Panel</span></div><a class="logout" href="/api/logout">Log out &rarr;</a></header>\n  <div class="bar"></div>\n  <div class="wrap">\n    <div class="hi">Welcome, Admin &#128075;</div>\n    <div class="sub">You are logged in. Choose an internal tool below. These are private to staff only.</div>\n    <div class="grid">\n      <a class="card" href="/app/letter"><div class="ico">&#128221;</div><h3>Letter Generator</h3><div class="open">Open tool &rarr;</div></a>\n      <a class="card" href="/app/rtgs"><div class="ico">&#128179;</div><h3>RTGS Letter Generator</h3><div class="open">Open tool &rarr;</div></a>\n      <a class="card" href="/app/id-card"><div class="ico">&#127183;</div><h3>BPCL ID Card Maker</h3><div class="open">Open tool &rarr;</div></a>\n    </div>\n  </div>\n  <footer>Private admin area &middot; P.G. Service Station</footer>\n</body></html>';
function decode(b64) { return Buffer.from(b64, "base64").toString("utf8"); }
function verify(token, secret) {
  if (!token || token.indexOf(".") === -1) return false;
  const idx = token.indexOf("."); const p = token.slice(0, idx); const sig = token.slice(idx + 1);
  const expected = crypto.createHmac("sha256", secret).update(p).digest("base64url");
  const A = Buffer.from(sig), B = Buffer.from(expected);
  if (A.length !== B.length || !crypto.timingSafeEqual(A, B)) return false;
  try { const payload = JSON.parse(Buffer.from(p, "base64url").toString("utf8")); return !!payload.exp && Date.now() < payload.exp; }
  catch { return false; }
}
function getCookie(event, name) {
  const h = event.headers.cookie || event.headers.Cookie || "";
  const part = h.split(/;\s*/).find((c) => c.indexOf(name + "=") === 0);
  return part ? decodeURIComponent(part.slice(name.length + 1)) : null;
}
function page(statusCode, bodyHtml) {
  return { statusCode, headers: {
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "no-store, no-cache, must-revalidate, private",
    "X-Frame-Options": "SAMEORIGIN", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer",
  }, body: bodyHtml };
}
exports.handler = async (event) => {
  const secret = process.env.SESSION_SECRET;
  if (!secret) return page(500, "<h1>Server not configured</h1><p>Set SESSION_SECRET.</p>");
  const authed = verify(getCookie(event, "pg_session"), secret);
  if (!authed) return { statusCode: 302, headers: { Location: "/login.html", "Cache-Control": "no-store" } };
  const q = (event.queryStringParameters && event.queryStringParameters.tool) || "";
  const path = event.path || "";
  if (q === "rtgs" || path.endsWith("/app/rtgs")) return page(200, decode(TOOLS["rtgs"]));
  if (q === "id-card" || path.endsWith("/app/id-card")) return page(200, decode(TOOLS["id-card"]));
  if (q === "letter" || path.endsWith("/app/letter")) return page(200, decode(TOOLS["letter"]));
  return page(200, DASHBOARD);
};
